    "content": "新华社北京9月14日电 2026年中国好人特别节目9月13日晚在中央广播电视总台央视综合频道首播，9月14日晚在中央广播电视总台央视社会与法频道重播。节目重点讲述了10人（组）平凡英雄的感人故事。 2026年是中国共产党成立105周年、红军长征胜利90周年，也是“十五五”开局之年。礼赞中国好人，既是向德行善举致敬，更是礼赞伟大时代，致敬每一位于平凡之中铸就不凡的中国人。在节目现场，2025年上榜中国好人代表动情讲述了助人为乐、见义勇为、诚实守信、敬业奉献、孝老爱亲的故事。他们中，有全身心扎根基层治理一线、以实干担当…"
