    "content": "最近桌面特别乱，fences 要钱，免费的 360 啊腾讯桌面有有隐私问题。搜了一下 v 站有个 openfence 但是功能有点孱弱。所以我选择 vibe 一个，基本就是照着 Fences 做的。Rust 写的,占用资源小，好看。 可以把桌面上的文件、文件夹和快捷方式放进不同的分组，支持拖动、缩放、自动分类，以及 Fluent / Liquid Glass 两种外观。 官网： pecofence.jiang.jp 源码和下载： GitHub / PecoFence 下面是两个小功能演示，可以去网站上看更多的演示。…"
