    "author": "鳝堂集庆",
    "description": "赵孟頫有些像金元四大家里的朱丹溪，都是能够充分吸收前人的精华为我所用并有所创新的集大成者。 有时生的晚也是有好处的，就是能够站在巨人的肩膀上少走些弯路。当然，有利就有弊。正是有了一批前人的开拓创新，这时想再创新更是难上加难了。 楷书到颜柳就是天花板了，以后再也没有人能超越他们，因而残唐五代、北宋南宋加起来近四百年，一直在模仿，没有出过一个楷书大家。 北宋最有名的宋四家都以行书见长，如石压蛤蟆的苏轼，树梢挂蛇、长枪大戟的黄庭坚，八面出锋的…",
    "content": "赵孟頫有些像金元四大家里的朱丹溪，都是能够充分吸收前人的精华为我所用并有所创新的集大成者。 有时生的晚也是有好处的，就是能够站在巨人的肩膀上少走些弯路。当然，有利就有弊。正是有了一批前人的开拓创新，这时想再创新更是难上加难了。 楷书到颜柳就是天花板了，以后再也没有人能超越他们，因而残唐五代、北宋南宋加起来近四百年，一直在模仿，没有出过一个楷书大家。 北宋最有名的宋四家都以行书见长，如石压蛤蟆的苏轼，树梢挂蛇、长枪大戟的黄庭坚，八面出锋的米芾，四家里面也就蔡苏楷书能拿的出手，但也都是学颜，特别是苏轼的楷书，简直就是他…"
