    "content": "IT之家 9 月 14 日消息，微软首席执行官萨蒂亚 · 纳德拉今天在 X 平台发文，谈及微软的前沿 AI 发展理念。 纳德拉表示，任何对超级智能的探索都必须在核心原则约束下运行：如果人们构建的 AI 无法帮助人类，且无法被人类控制，那么它就不值得发展。他认为 AI 需要加速发展，使其成果能够得到广泛传播，惠及不同国家、社区和企业。这显然需要建立前沿生态，让开源和闭源模型都能蓬勃发展。 对企业来说，这意味着他们必须完全掌握自身独有的隐性知识。每家公司都应该可以构建属于自己的、持续学习闭环、不断迭代的系统，而不必依赖…"
