    "description": "新华社斯德哥尔摩9月13日电（记者朱昊晨 褚怡）瑞典东南部东约特兰省芬斯蓬镇13日晚发生枪击事件，两人受伤，多人被捕。事件发生于瑞典议会选举当天。 据瑞典警方消息，两名伤者在一辆汽车内被发现，均受枪伤，随后被送往医院；事发时车内还有第三人。 警方说，多人因涉嫌与这起枪击案有关被捕。警方已对此案启动初步调查。目前伤者情况以及事件相关细节尚未公布。 枪击案消息传出时，正值瑞典议会选举当晚。治安和犯罪问题是此次瑞典议会选举期间受到关注的议题之…",
    "content": "新华社斯德哥尔摩9月13日电（记者朱昊晨 褚怡）瑞典东南部东约特兰省芬斯蓬镇13日晚发生枪击事件，两人受伤，多人被捕。事件发生于瑞典议会选举当天。 据瑞典警方消息，两名伤者在一辆汽车内被发现，均受枪伤，随后被送往医院；事发时车内还有第三人。 警方说，多人因涉嫌与这起枪击案有关被捕。警方已对此案启动初步调查。目前伤者情况以及事件相关细节尚未公布。 枪击案消息传出时，正值瑞典议会选举当晚。治安和犯罪问题是此次瑞典议会选举期间受到关注的议题之一。"
