    "content": "IT之家 9 月 14 日消息，苹果现已更新旗下 App Store 审核指南 4.3 (b) 条款，官方将移除长期未更新或无法吸引用户的“约会、手电筒、壁纸、音效、简单计时器、算命”等类型应用。 苹果在 4.3 (b) 中表示，目前 App Store 中已存在大量约会、手电筒、音效、壁纸、简单计时器、算命等应用，因此除非能够提供具有明显差异或改进的体验，否则苹果不会接受新的相关应用提交。同时，苹果表示，如果这类已经存在的应用没有获得更新、改进或者无法吸引用户，未来可能会将其从 App Store 中移除。 除此…"
