    "content": "新华社雅典9月13日电（记者陈刚 刘白云）据希腊国家广播电视公司报道，一艘载有外国移民的船只当地时间13日晚在希腊南部海域倾覆，附近过往船只已救起数十人，仍有约25人失踪。 报道称，事发海域当时刮西北风，风力达到4级。目前无法获知涉事船只的具体型号、船名和登记情况。 希腊海岸警卫部门已在事发的克里特岛以南加夫多斯岛附近海域展开大规模搜救行动，另有4艘附近航行的船只和两艘欧洲边境和海岸警卫队船只参与搜救。 报道称，已救起的52人中有一人失去意识。据获救人员说，事发时船上约有77人。 加夫多斯岛位于希腊最南端。近年来，…"
