    "content": "近日，克罗地亚布拉奇岛发生大规模山火。当地时间12日夜间，火势向该岛的米尔纳镇及附近海湾蔓延，近700名当地居民和游客被紧急疏散。当地消防部门出动了4架消防飞机参与灭火。13日，山火仍未被完全扑灭，目前过火面积已达到3500公顷。"
