    "description": "新华社布宜诺斯艾利斯9月13日电（记者张铎）阿根廷国防部长卡洛斯·阿尔韦托·普雷斯蒂13日表示，美国政府并未在马尔维纳斯群岛（简称马岛，英国称福克兰群岛）主权争端中偏向某一方。 普雷斯蒂13日接受媒体采访时说，美国政府支持和平解决马岛主权争端，并未偏向阿根廷或英国。 普雷斯蒂表示，所有阿根廷人都知道，恢复马岛主权是一项国家事业，实现这一目标的唯一途径就是通过外交手段。他同时强调，国防也是一种外交工具。 美国总统特朗普8月31日公开表示或…",
    "content": "新华社布宜诺斯艾利斯9月13日电（记者张铎）阿根廷国防部长卡洛斯·阿尔韦托·普雷斯蒂13日表示，美国政府并未在马尔维纳斯群岛（简称马岛，英国称福克兰群岛）主权争端中偏向某一方。 普雷斯蒂13日接受媒体采访时说，美国政府支持和平解决马岛主权争端，并未偏向阿根廷或英国。 普雷斯蒂表示，所有阿根廷人都知道，恢复马岛主权是一项国家事业，实现这一目标的唯一途径就是通过外交手段。他同时强调，国防也是一种外交工具。 美国总统特朗普8月31日公开表示或将重新考虑美国政府在马岛主权争端中的立场。据美联社报道，特朗普12日在访问爱尔兰…"
