    "content": "13/09/2026 - 22:44 乌克兰总统泽连斯基周日（9月13日）对其前新闻秘书实施制裁，并指控她与另外9人传播俄罗斯宣传、支持俄罗斯对乌克兰采取的侵略政策。尤莉娅·门德尔（Yuliia Mendel）曾于2019年至2021年担任泽连斯基的新闻秘书，当时俄乌战争尚未全面爆发。 根据泽连斯基签署的法令，此次制裁期限为10年，包括冻结资产以及限制贸易等措施。 门德尔随后在Facebook上发文回应称，对乌克兰公民实施制裁违反宪法，但没有就相关具体指控发表评论。 自去年以来，门德尔曾多次接受采访，对泽连斯基的执…"
