    "content": "13/09/2026 - 20:16 法新社周日（9月13日）消息称，在一项备受期待的民调（ Ipsos-BVA ）中，结果显示，有33%至35%的人表示打算投票支持极右翼国民联盟候选人勒庞，她大幅领先于其他候选人。在所测试的六种候选人组合中，极左翼法国不屈服党候选人梅朗雄有四种情形能够进入第二轮，排名第二，以15.5%至17%的投票意向率与勒庞一同进入第二轮。 此次调查共采访了超过13000人。根据这项调查，法国人有71%希望总统大选能够带来“真正的社会和政治变革”，这一比例明显高于2022年总统大选前的51%。…"
