    "content": "当地时间9月13日上午，国家主席习近平在新德里出席金砖国家领导人第十八次会晤第二阶段会议，并发表题为《筑牢金砖合作根基 壮大全球南方力量》的重要讲话。 多国人士在接受新华社记者采访时表示，面对变乱交织的国际形势，习近平主席就金砖国家把握历史主动、团结广大全球南方国家发挥更大作用阐述中国主张，提出中国倡议，为“大金砖合作”指引前进方向。相信在中国引领推动下，金砖国家将勠力同心、携手共进，共同书写全球南方团结自强新篇章。 把准大势，勇担时代使命 “要让世界稳下来、好起来，金砖国家必须把握历史主动，团结广大全球南方国家，…"
