    "title": "近千名民间文艺工作者亮相第十五届中国民间艺术节",
    "link": "http://www.news.cn/20260913/3833054fde91415b969b57f2bd2cefc0/c.html",
    "pub_date": "2026-09-13 23:52:02",
    "author": "李庚辰",
    "description": "新华社西安9月13日电（记者李庚辰）9月13日晚，第十五届中国民间艺术节开幕式文艺演出在陕西榆林举行，来自全国16个省（区、市）的近千名民间文艺工作者参演参展，为现场观众奉上一场兼具浓郁地域特色与鲜活民族风韵的文艺视听盛宴。 本届艺术节开幕式内容多元、亮点纷呈。重庆苗族民歌《娇阿依》、陕北民歌《一对对鸳鸯水上漂》、江西客家民歌《牛牯调》、云南白族民歌《剑川东山放羊调》等经典节目惊艳亮相，展现了中国民间文艺百花齐放的繁荣风貌与蓬勃向上的时…",
    "content": "新华社西安9月13日电（记者李庚辰）9月13日晚，第十五届中国民间艺术节开幕式文艺演出在陕西榆林举行，来自全国16个省（区、市）的近千名民间文艺工作者参演参展，为现场观众奉上一场兼具浓郁地域特色与鲜活民族风韵的文艺视听盛宴。 本届艺术节开幕式内容多元、亮点纷呈。重庆苗族民歌《娇阿依》、陕北民歌《一对对鸳鸯水上漂》、江西客家民歌《牛牯调》、云南白族民歌《剑川东山放羊调》等经典节目惊艳亮相，展现了中国民间文艺百花齐放的繁荣风貌与蓬勃向上的时代活力。 本届艺术节持续至21日，将配套推出民间文艺快闪展演、民间文艺家传作品展…"
