    "description": "新华社伦敦9月13日电（记者张枫）美国总统特朗普13日在访问爱尔兰期间表示，乌克兰总统泽连斯基“必须停止”对俄罗斯炼油厂的攻击。 特朗普当天在接受采访时说，他已就乌克兰停止攻击俄罗斯炼油厂问题与泽连斯基进行过沟通，并强调乌方“必须停止”攻击。 本月5日和6日，美国代表团先后访问莫斯科和基辅。美国总统特使威特科夫称，此访旨在推动进一步对话以结束俄乌战事。",
    "content": "新华社伦敦9月13日电（记者张枫）美国总统特朗普13日在访问爱尔兰期间表示，乌克兰总统泽连斯基“必须停止”对俄罗斯炼油厂的攻击。 特朗普当天在接受采访时说，他已就乌克兰停止攻击俄罗斯炼油厂问题与泽连斯基进行过沟通，并强调乌方“必须停止”攻击。 本月5日和6日，美国代表团先后访问莫斯科和基辅。美国总统特使威特科夫称，此访旨在推动进一步对话以结束俄乌战事。"
