    "content": "从优新品种集中亮相，到深加工技术迭代升级，再到人工智能全链赋能，种业振兴正沿着“育种—加工—数智”三个层级持续进阶。9月10日至12日，第十八届中国国际种业博览会暨第二十三届全国种子信息交流与产品交易会（简称“全国种子双交会”）在安徽合肥举办。大会聚焦“数智强芯”和“全链振兴”，吸引众多专家学者、种子企业参展参会。 “这是我们的中蜜1号西瓜，最大特点就是果皮韧性强，运输磕碰几乎零损耗。”在国投丰乐种业股份有限公司展台前，工作人员介绍说，作为大会首次发布的“十四五”国家农作物育种联合攻关成果之一，中蜜1号西瓜果肉脆爽…"
