    "content": "新华社成都9月13日电（记者陈地）13日，2026年WDSF（世界体育舞蹈联合会）世界霹雳舞3V3混合团体锦标赛决赛在成都打响。由郭朴、商小宇、李后桦组成的中国霹雳舞队战胜同样来自中国的“为爱而舞”战队，夺得冠军。 据了解，今年WDSF创新推出3V3混合团体项目，并首次将比赛纳入世锦赛赛事体系，因此本次决出的也是该项目首枚世锦赛金牌。 本次世锦赛于12日在成都城北体育馆开战，共吸引全球41支队伍参加。中国国家队队员郭朴、商小宇、李后桦组成中国霹雳舞队参赛，他们配合默契，节奏流畅，凭借出色的舞技一路过关斩将，闯进决赛…"
