    "content": "新华社海口9月13日电（记者吴茂辉、夏天）受热带低压和冷空气共同影响，海南多地出现持续强降雨。记者从海南省防灾减灾救灾委员会办公室获悉，截至13日19时50分，全省已紧急转移危险区域群众31564人，未接报重大灾情险情，无人员伤亡。 9月11日8时至13日16时，万宁、陵水、琼中、五指山、琼海、保亭6个市县24个乡镇雨量超过300毫米，最大为万宁市长丰镇452.1毫米。预计13日傍晚至14日仍有200至300毫米、局地450毫米降雨，严重影响时段集中在今日夜间至明日白天，防御形势较严峻。 海南省防灾减灾救灾委员会1…"
